files.make_deck.js:
const pptxgen = require("pptxgenjs");
const pptx = new pptxgen();
const s1 = pptx.addSlide();
s1.addText("Made on the phone", { x: 1, y: 1, fontSize: 32 });
const s2 = pptx.addSlide();
s2.addText("Slide two", { x: 1, y: 1, fontSize: 24 });
pptx.writeFile({ fileName: "deck.pptx" }).then((name) => console.log("saved", name));

files.make_doc.mjs:
import * as fs from "fs";
import { Document, Packer, Paragraph, TextRun } from "docx";
const doc = new Document({ sections: [{ children: [new Paragraph({ children: [new TextRun("Made with docx on the phone")] })] }] });
const buf = await Packer.toBuffer(doc);
fs.writeFileSync("note.docx", buf);
console.log("bytes", buf.length > 1000);
